from collections import defaultdict
import heapq
def topological(edges, nodes):
    adj = defaultdict(list)
    indegree = {node: 0 for node in nodes}
    seen = set()
    for u, v in edges:
        if (u, v) in seen:
            continue
        seen.add((u, v))
        adj[u].append(v)
        indegree[v] += 1
    zero = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(zero)
    result = []
    while zero:
        node = heapq.heappop(zero)
        result.append(node)
        for nb in adj[node]:
            indegree[nb] -= 1
            if indegree[nb] == 0:
                heapq.heappush(zero, nb)
    if len(result) != len(nodes):
        raise ValueError("Cycle")
    return result

