from collections import defaultdict, deque

def rate_limit(events, limit, window):
    if limit == 0:
        return [False] * len(events)
    queues = defaultdict(deque)
    result = []
    for t, key in events:
        q = queues[key]
        # Remove events that are outside the window
        while q and q[0] <= t - window:
            q.popleft()
        if len(q) < limit:
            q.append(t)
            result.append(True)
        else:
            result.append(False)
    return result
